    "sourceExcerpt": "Infrastructure and Environment Overview (โครงสร้างระบบ) โปรแกรม My Inventory สรุปโครงสร้างการทำงาน ระบบ และสิ่งแวดล้อมทางเทคโนโลยี (Infrastructure & Environment Overview) ได้ดังนี้ครับ: 1. ข้อมูลนำเข้าและจุดเริ่มต้นระบบ (Data Input & Planning) ระบบเริ่มต้นจากการรับแผนงาน (Planning) ซึ่งรองรับระบบสภาพแวดล้อมการทำงาน 2 รูปแบบหลัก: การเชื่อมต่อข้อมูลภายนอก (File Integration): รองรับการอัปโหลดไฟล์ในรูปแบบ Excel File เพื่อนำเข้าแผนข้อมูลจำนวนมากอย่างรวดเร็ว (เช่น แผนการรับเข้า/แผนการจัดส่ง) การบันทึกข้อมูลหน้าจอ (Manual Input System): มีระบบหน้าจอ User Interface (UI) ให้เจ้าหน้าที่สามารถพิมพ์คีย์ข้อมูลเข้าระบบได้โดยตรง (Manual Key) 2. อุปกรณ์และเทคโนโลยีในระบบคลังสินค้า (Hardware & IoT Environment) ในส่วนของหน้างาน (Operation) ระบบมีการเชื่อมต่อกับอุปกรณ์ฮาร์ดแวร์ภายนอกเพื่อช่วยในการทำงานแบบ Real-time: เครื่องพิมพ์บาร์โค้ด/แท็ก (Barcode & Label Printer): ใช้สำหรับพิมพ์ฉลาก (Label Tag) ที่มีทั้งบาร์โค้ด 1D หรือ QR Code เพื่อใช้ติดกับตัวสินค้าตั้งแต่ขั้นตอนการรับเข้า Infrastructure and Environment Overview (โครงสร้างระบบและสภาพแวดล้อม) เพิ่มเติมจากแผนภาพเดิมได้ดังนี้ครับ: 1. ขอบเขตการใช้งานและการปรับใช้ระบบ (System Deployment & Scope) Exclusive Single-Company System: ระบบนี้ถูกออกแบบและพัฒนาขึ้นเพื่อใช้งานอย่างเป็นทางการให้กับบริษัท XXXXXX (Thailand) Co., Ltd เป็นการเฉพาะเจาะจงเพียงบริษัทเดียวเท่านั้น ไม่ได้เปิดให้บุคคลภายนอกหรือบริษัทอื่นเข้ามาใช้ร่วมกัน (Single-Tenant Environment) Strict Scope Adherence: สภาพแวดล้อมของฟังก์ชันการทำงานทั้งหมด ถูกจำกัดและพัฒนาขึ้นตามขอบเขตข้อกำหนด (Requirement Document) ที่ได้ตกลงไว้ในเอกสารอย่างเคร่งครัด โดยมุ่งเน้นไปที่โมดูลการบริหารจัดการคลังสินค้าภายใต้โปรแกรม My Inventory เท่านั้น 2. สถาปัตยกรรมข้อมูลและการจัดการสิทธิ์ (Data Architecture & Multi-Tenancy) Single-Owner Architecture: ในโครงสร้างฐานข้อมูล (Database Schema) ของระบบ WMS นี้ จะม",
