    "sourceExcerpt": "ใช้สำหรับสร้างและดูแลข้อมูลสินค้าในระบบ เข้าสู่เมนูที่เกี่ยวข้องจากโครงสร้างเมนูหลักของระบบ ตรวจสอบข้อมูลอ้างอิง เช่น รหัสเอกสาร ผู้เกี่ยวข้อง วันที่ หรือสถานะที่ปรากฏบนหน้าจอ กรอกข้อมูลในฟิลด์ที่จำเป็น หรือเลือกคำสั่งจากปุ่ม/แถบเครื่องมือให้ครบถ้วน ทบทวนรายการในตารางหรือค่าที่ผู้ใช้สแกน/ป้อนก่อนบันทึก ยืนยัน หรือพิมพ์เอกสาร ผู้ปฏิบัติงานเปิดเมนู Import Manager เพื่อใช้งานหน้าจอ Import Item โดยใช้ข้อมูลจากเอกสารอ้างอิงหรือการสแกนบาร์โค้ด จากนั้นตรวจสอบผลลัพธ์ว่ารายการได้รับการบันทึกและเปลี่ยนสถานะถูกต้อง ควรตรวจสอบหน่วยนับ สถานะควบคุมล็อต/วันหมดอายุ/Serial ก่อนบันทึก ข้อมูลสินค้าใหม่พร้อมใช้งานในธุรกรรมอื่น หมายเหตุ: คำอธิบายหน้าจอนี้ยึดตามภาพที่มองเห็นได้และชื่อไฟล์อ้างอิงเป็นหลัก หากบางฟิลด์หรือสิทธิ์ไม่ปรากฏในระบบจริง ให้ยึดตามการตั้งค่าหน่วยงานและบทบาทผู้ใช้ 58. Import Item / BrowseExcelFile ผู้ปฏิบัติงานเปิดเมนู Import Manager เพื่อใช้งานหน้าจอ Import Item / BrowseExcelFile โดยใช้ข้อมูลจากเอกสารอ้างอิงหรือการสแกนบาร์โค้ด จากนั้นตรวจสอบผลลัพธ์ว่ารายการได้รับการบันทึกและเปลี่ยนสถานะถูกต้อง 59. Import Item / DownloadTemplate",
