    "sourceExcerpt": "ใช้สำหรับนำเข้าข้อมูลจากไฟล์ต้นแบบ เข้าสู่เมนูที่เกี่ยวข้องจากโครงสร้างเมนูหลักของระบบ ตรวจสอบข้อมูลอ้างอิง เช่น รหัสเอกสาร ผู้เกี่ยวข้อง วันที่ หรือสถานะที่ปรากฏบนหน้าจอ กรอกข้อมูลในฟิลด์ที่จำเป็น หรือเลือกคำสั่งจากปุ่ม/แถบเครื่องมือให้ครบถ้วน ทบทวนรายการในตารางหรือค่าที่ผู้ใช้สแกน/ป้อนก่อนบันทึก ยืนยัน หรือพิมพ์เอกสาร ผู้ปฏิบัติงานเปิดเมนู Import Manager เพื่อใช้งานหน้าจอ Import Location โดยใช้ข้อมูลจากเอกสารอ้างอิงหรือการสแกนบาร์โค้ด จากนั้นตรวจสอบผลลัพธ์ว่ารายการได้รับการบันทึกและเปลี่ยนสถานะถูกต้อง ควรดาวน์โหลด Template ล่าสุดก่อนกรอกข้อมูล ตรวจสอบ Column Mapping ให้ตรงกับรูปแบบข้อมูล ข้อมูลถูกนำเข้าสู่ระบบตามรูปแบบที่กำหนด หมายเหตุ: คำอธิบายหน้าจอนี้ยึดตามภาพที่มองเห็นได้และชื่อไฟล์อ้างอิงเป็นหลัก หากบางฟิลด์หรือสิทธิ์ไม่ปรากฏในระบบจริง ให้ยึดตามการตั้งค่าหน่วยงานและบทบาทผู้ใช้ 61. Import Location / BrowseExcelFile ผู้ปฏิบัติงานเปิดเมนู Import Manager เพื่อใช้งานหน้าจอ Import Location / BrowseExcelFile โดยใช้ข้อมูลจากเอกสารอ้างอิงหรือการสแกนบาร์โค้ด จากนั้นตรวจสอบผลลัพธ์ว่ารายการได้รับการบันทึกและเปลี่ยนสถานะถูกต้อง 62. Import Location / DownloadTemplate",
    "screenDescription": "หน้าจอ Import Location อยู่ในหมวด การจัดการ Master Data ใช้สำหรับ เตรียมและนำเข้าข้อมูลเข้าสู่ระบบอย่างถูกต้อง ผู้ใช้งานควรตรวจสอบส่วน Header, Search/Filter, Detail Grid, Action Buttons, Status และข้อความแจ้งเตือนก่อนยืนยันรายการ",
