    "sourceExcerpt": "48. Import Business Partner ใช้สำหรับจัดเก็บข้อมูลคู่ค้า ลูกค้า หรือผู้เกี่ยวข้องทางธุรกิจ เข้าสู่เมนูที่เกี่ยวข้องจากโครงสร้างเมนูหลักของระบบ ตรวจสอบข้อมูลอ้างอิง เช่น รหัสเอกสาร ผู้เกี่ยวข้อง วันที่ หรือสถานะที่ปรากฏบนหน้าจอ กรอกข้อมูลในฟิลด์ที่จำเป็น หรือเลือกคำสั่งจากปุ่ม/แถบเครื่องมือให้ครบถ้วน ทบทวนรายการในตารางหรือค่าที่ผู้ใช้สแกน/ป้อนก่อนบันทึก ยืนยัน หรือพิมพ์เอกสาร ผู้ปฏิบัติงานเปิดเมนู Import Manager เพื่อใช้งานหน้าจอ Import Business Partner โดยใช้ข้อมูลจากเอกสารอ้างอิงหรือการสแกนบาร์โค้ด จากนั้นตรวจสอบผลลัพธ์ว่ารายการได้รับการบันทึกและเปลี่ยนสถานะถูกต้อง ตรวจสอบประเภทคู่ค้าและข้อมูลติดต่อก่อนบันทึก สามารถเรียกใช้ข้อมูลคู่ค้าในเอกสารรับและจ่ายสินค้าได้ หมายเหตุ: คำอธิบายหน้าจอนี้ยึดตามภาพที่มองเห็นได้และชื่อไฟล์อ้างอิงเป็นหลัก หากบางฟิลด์หรือสิทธิ์ไม่ปรากฏในระบบจริง ให้ยึดตามการตั้งค่าหน่วยงานและบทบาทผู้ใช้ 49. Import Business Partner / BrowseExcelFile ผู้ปฏิบัติงานเปิดเมนู Import Manager เพื่อใช้งานหน้าจอ Import Business Partner / BrowseExcelFile โดยใช้ข้อมูลจากเอกสารอ้างอิงหรือการสแกนบาร์โค้ด จากนั้นตรวจสอบผลลัพธ์ว่ารายการได้รับการบันทึกและเปลี่ยนสถานะถูกต้อง 50. Import Business Partner / DownloadTemplate",
