    "sourceExcerpt": "WMS (Warehouse Management System Database): ถือเป็นหัวใจหลักหรือเซิร์ฟเวอร์กลางของโปรแกรม My Inventory ทำหน้าที่เป็นฐานข้อมูลกลาง (Centralized Database) คอยรับสัญญาณ Data Packet จากอุปกรณ์ PDA และคอมพิวเตอร์ เพื่อประมวลผลและอัปเดตสถานะสินค้าคงคลังแบบเรียลไทม์ (Update Inventory) ในทุก ๆ จุดเปลี่ยนของสถานะสินค้า 4. โครงสร้างกระบวนการทางธุรกิจ (Business Process Overview) ระบบถูกแบ่งสถาปัตยกรรมกระบวนการออกเป็น 5 ส่วนหลัก (ตามคอลัมน์ Swimlane) เพื่อให้ง่ายต่อการจัดการสิทธิ์การใช้งาน (User Roles) และการไหลของข้อมูล: Create Plan (การวางแผน): จัดการเอกสารฝั่งขาเข้า (Inbound Plan) และขาออก (Outbound Plan) Supplier (ซัพพลายเออร์): จุดเชื่อมต่อข้อมูลเมื่อซัพพลายเออร์มาส่งสินค้า (Loading) Inbound (กระบวนการขาเข้า): ควบคุมการพิมพ์แท็ก, ตรวจรับผ่าน PDA, ผ่านระบบควบคุมคุณภาพ (QC), และระบุตำแหน่งจัดเก็บ (Put-away) พร้อมอัปเดตยอดเข้า WMS Outbound (กระบวนการขาออก): ระบบคำนวณการจัดสรรสินค้า (Allocate Product), สั่งงานไปที่ PDA เพื่อหยิบสินค้า (Picking), และทำรายการยืนยันการขึ้นรถ (Confirm Ship) Delivery (การจัดส่ง): ขั้นตอนสุดท้ายในการตัดสต็อกและบันทึกข้อมูลการปล่อยรถขนส่งสินค้า (ส่งสินค้า) เพื่อปิดงาน",
