    "sourceExcerpt": "ใช้สำหรับดำเนินงานตามเมนูที่แสดงในหน้าจอนี้ เข้าสู่เมนูที่เกี่ยวข้องจากโครงสร้างเมนูหลักของระบบ ตรวจสอบข้อมูลอ้างอิง เช่น รหัสเอกสาร ผู้เกี่ยวข้อง วันที่ หรือสถานะที่ปรากฏบนหน้าจอ กรอกข้อมูลในฟิลด์ที่จำเป็น หรือเลือกคำสั่งจากปุ่ม/แถบเครื่องมือให้ครบถ้วน ทบทวนรายการในตารางหรือค่าที่ผู้ใช้สแกน/ป้อนก่อนบันทึก ยืนยัน หรือพิมพ์เอกสาร ผู้ปฏิบัติงานเปิดเมนู Master เพื่อใช้งานหน้าจอ ZoneLocation โดยใช้ข้อมูลจากเอกสารอ้างอิงหรือการสแกนบาร์โค้ด จากนั้นตรวจสอบผลลัพธ์ว่ารายการได้รับการบันทึกและเปลี่ยนสถานะถูกต้อง ควรตรวจสอบข้อมูลก่อนกดบันทึกหรือยืนยัน หากมีฟิลด์บังคับต้องกรอกข้อมูลให้ครบถ้วน ระบบบันทึกหรือแสดงผลตามคำสั่งที่ผู้ใช้ดำเนินการ หมายเหตุ: คำอธิบายหน้าจอนี้ยึดตามภาพที่มองเห็นได้และชื่อไฟล์อ้างอิงเป็นหลัก หากบางฟิลด์หรือสิทธิ์ไม่ปรากฏในระบบจริง ให้ยึดตามการตั้งค่าหน่วยงานและบทบาทผู้ใช้ 135. ZoneLocation / AddZone ผู้ปฏิบัติงานเปิดเมนู Master เพื่อใช้งานหน้าจอ ZoneLocation / AddZone โดยใช้ข้อมูลจากเอกสารอ้างอิงหรือการสแกนบาร์โค้ด จากนั้นตรวจสอบผลลัพธ์ว่ารายการได้รับการบันทึกและเปลี่ยนสถานะถูกต้อง 136. ZoneLocation / Assign ZoneLocation",
