    "sourceExcerpt": "ผู้ปฏิบัติงานเปิดเมนู Inbound Order / Mobile Blind Recript เพื่อใช้งานหน้าจอ Blind Recript โดยใช้ข้อมูลจากเอกสารอ้างอิงหรือการสแกนบาร์โค้ด จากนั้นตรวจสอบผลลัพธ์ว่ารายการได้รับการบันทึกและเปลี่ยนสถานะถูกต้อง ตรวจสอบ Supplier วันที่คาดว่าจะรับ และจำนวนสั่งก่อนบันทึก เอกสารสินค้าเข้าสามารถนำไปใช้ในขั้นตอนรับจริงและจัดเก็บต่อได้ หมายเหตุ: คำอธิบายหน้าจอนี้ยึดตามภาพที่มองเห็นได้และชื่อไฟล์อ้างอิงเป็นหลัก หากบางฟิลด์หรือสิทธิ์ไม่ปรากฏในระบบจริง ให้ยึดตามการตั้งค่าหน่วยงานและบทบาทผู้ใช้ ผู้ปฏิบัติงานเปิดเมนู Inbound Order / Mobile Blind Recript เพื่อใช้งานหน้าจอ Blind Recript / Add โดยใช้ข้อมูลจากเอกสารอ้างอิงหรือการสแกนบาร์โค้ด จากนั้นตรวจสอบผลลัพธ์ว่ารายการได้รับการบันทึกและเปลี่ยนสถานะถูกต้อง ผู้ปฏิบัติงานเปิดเมนู Inbound Order / Mobile Blind Recript เพื่อใช้งานหน้าจอ Blind Recript / Qty โดยใช้ข้อมูลจากเอกสารอ้างอิงหรือการสแกนบาร์โค้ด จากนั้นตรวจสอบผลลัพธ์ว่ารายการได้รับการบันทึกและเปลี่ยนสถานะถูกต้อง ผู้ปฏิบัติงานเปิดเมนู Inbound Order / Mobile เพื่อใช้งานหน้าจอ InboundReceipt โดยใช้ข้อมูลจากเอกสารอ้างอิงหรือการสแกนบาร์โค้ด จากนั้นตรวจสอบผลลัพธ์ว่ารายการได้รับการบันทึกและเปลี่ยนสถานะถูกต้อง 74. InboundReceipt / ReceiptItem",
