    "sourceExcerpt": "อุปกรณ์พกพาขนาดเล็ก (PDA / Handheld Terminal): เป็นสภาพแวดล้อมการทำงานแบบ Mobile Application ที่เจ้าหน้าที่คลังสินค้าใช้สแกนบาร์โค้ดในกิจกรรมต่าง ๆ เช่น การตรวจรับสินค้า (Receive), การย้ายตำแหน่งจัดเก็บ (Move to Location) และการหยิบสินค้า (Picking) ทำให้ลดความผิดพลาดและทำงานได้คล่องตัว 3. ระบบฐานข้อมูลและการประมวลผลกลาง (Core System & Database) WMS (Warehouse Management System Database): ถือเป็นหัวใจหลักหรือเซิร์ฟเวอร์กลางของโปรแกรม My Inventory ทำหน้าที่เป็นฐานข้อมูลกลาง (Centralized Database) คอยรับสัญญาณ Data Packet จากอุปกรณ์ PDA และคอมพิวเตอร์ เพื่อประมวลผลและอัปเดตสถานะสินค้าคงคลังแบบเรียลไทม์ (Update Inventory) ในทุก ๆ จุดเปลี่ยนของสถานะสินค้า 4. โครงสร้างกระบวนการทางธุรกิจ (Business Process Overview) ระบบถูกแบ่งสถาปัตยกรรมกระบวนการออกเป็น 5 ส่วนหลัก (ตามคอลัมน์ Swimlane) เพื่อให้ง่ายต่อการจัดการสิทธิ์การใช้งาน (User Roles) และการไหลของข้อมูล: Create Plan (การวางแผน): จัดการเอกสารฝั่งขาเข้า (Inbound Plan) และขาออก (Outbound Plan) Supplier (ซัพพลายเออร์): จุดเชื่อมต่อข้อมูลเมื่อซัพพลายเออร์มาส่งสินค้า (Loading) Inbound (กระบวนการขาเข้า): ควบคุมการพิมพ์แท็ก, ตรวจรับผ่าน PDA, ผ่านระบบควบคุมคุณภาพ (QC), และระบุตำแหน่งจัดเก็บ (Put-away) พร้อมอัปเดตยอดเข้า WMS",
    "screenDescription": "หน้าจอ Picking อยู่ในหมวด การเบิกสินค้า ใช้สำหรับ เตรียมสินค้าออกตามคำสั่งเบิก/ขาย ผู้ใช้งานควรตรวจสอบส่วน Header, Search/Filter, Detail Grid, Action Buttons, Status และข้อความแจ้งเตือนก่อนยืนยันรายการ",
