    "sourceExcerpt": "การจัดเตรียมก่อนจัดส่งจากข้อมูลที่มีในชุดภาพ ในชุดภาพอ้างอิงไม่พบหน้าจอ Packing แยกต่างหากอย่างชัดเจน จึงอธิบายจากภาพ Outbound, Picking Slip และ Delivery Note ที่เกี่ยวข้อง พร้อมระบุหมายเหตุในแต่ละจุด การจัดส่งสินค้า (Shipping) การปล่อยงานและเอกสารส่งมอบ ใช้สำหรับสร้างเอกสารจ่ายสินค้าและเตรียมการจัดส่ง เข้าสู่เมนูที่เกี่ยวข้องจากโครงสร้างเมนูหลักของระบบ 156. Outbound Order / PrintReportDelivery Note ตรวจสอบข้อมูลอ้างอิง เช่น รหัสเอกสาร ผู้เกี่ยวข้อง วันที่ หรือสถานะที่ปรากฏบนหน้าจอ กรอกข้อมูลในฟิลด์ที่จำเป็น หรือเลือกคำสั่งจากปุ่ม/แถบเครื่องมือให้ครบถ้วน ทบทวนรายการในตารางหรือค่าที่ผู้ใช้สแกน/ป้อนก่อนบันทึก ยืนยัน หรือพิมพ์เอกสาร ผู้ปฏิบัติงานเปิดเมนู Outbound Order / PC เพื่อใช้งานหน้าจอ Outbound Order / PrintReportDelivery Note โดยใช้ข้อมูลจากเอกสารอ้างอิงหรือการสแกนบาร์โค้ด จากนั้นตรวจสอบผลลัพธ์ว่ารายการได้รับการบันทึกและเปลี่ยนสถานะถูกต้อง ตรวจสอบวันส่ง แผนการจัดส่ง และรายการสินค้าให้ครบถ้วน เอกสารจ่ายสินค้าพร้อมสำหรับการปล่อยงาน หยิบ และพิมพ์เอกสาร หมายเหตุ: คำอธิบายหน้าจอนี้ยึดตามภาพที่มองเห็นได้และชื่อไฟล์อ้างอิงเป็นหลัก หากบางฟิลด์หรือสิทธิ์ไม่ปรากฏในระบบจริง ให้ยึดตามการตั้งค่าหน่วยงานและบทบาทผู้ใช้ 157. Outbound Order / PrintReportPicking Slip",
