    "sourceExcerpt": "ใช้สำหรับย้ายตำแหน่งจัดเก็บสินค้า เข้าสู่เมนูที่เกี่ยวข้องจากโครงสร้างเมนูหลักของระบบ ตรวจสอบข้อมูลอ้างอิง เช่น รหัสเอกสาร ผู้เกี่ยวข้อง วันที่ หรือสถานะที่ปรากฏบนหน้าจอ กรอกข้อมูลในฟิลด์ที่จำเป็น หรือเลือกคำสั่งจากปุ่ม/แถบเครื่องมือให้ครบถ้วน ทบทวนรายการในตารางหรือค่าที่ผู้ใช้สแกน/ป้อนก่อนบันทึก ยืนยัน หรือพิมพ์เอกสาร ผู้ปฏิบัติงานเปิดเมนู Inventory / Mobile Move เพื่อใช้งานหน้าจอ Inventory Move โดยใช้ข้อมูลจากเอกสารอ้างอิงหรือการสแกนบาร์โค้ด จากนั้นตรวจสอบผลลัพธ์ว่ารายการได้รับการบันทึกและเปลี่ยนสถานะถูกต้อง ตรวจสอบตำแหน่งต้นทางและปลายทางก่อนยืนยัน สินค้าเปลี่ยนตำแหน่งจัดเก็บตามคำสั่ง หมายเหตุ: คำอธิบายหน้าจอนี้ยึดตามภาพที่มองเห็นได้และชื่อไฟล์อ้างอิงเป็นหลัก หากบางฟิลด์หรือสิทธิ์ไม่ปรากฏในระบบจริง ให้ยึดตามการตั้งค่าหน่วยงานและบทบาทผู้ใช้",
