    "sourceExcerpt": "การบันทึกข้อมูลหน้าจอ (Manual Input System): มีระบบหน้าจอ User Interface (UI) ให้เจ้าหน้าที่สามารถพิมพ์คีย์ข้อมูลเข้าระบบได้โดยตรง (Manual Key) 2. อุปกรณ์และเทคโนโลยีในระบบคลังสินค้า (Hardware & IoT Environment) ในส่วนของหน้างาน (Operation) ระบบมีการเชื่อมต่อกับอุปกรณ์ฮาร์ดแวร์ภายนอกเพื่อช่วยในการทำงานแบบ Real-time: เครื่องพิมพ์บาร์โค้ด/แท็ก (Barcode & Label Printer): ใช้สำหรับพิมพ์ฉลาก (Label Tag) ที่มีทั้งบาร์โค้ด 1D หรือ QR Code เพื่อใช้ติดกับตัวสินค้าตั้งแต่ขั้นตอนการรับเข้า อุปกรณ์พกพาขนาดเล็ก (PDA / Handheld Terminal): เป็นสภาพแวดล้อมการทำงานแบบ Mobile Application ที่เจ้าหน้าที่คลังสินค้าใช้สแกนบาร์โค้ดในกิจกรรมต่าง ๆ เช่น การตรวจรับสินค้า (Receive), การย้ายตำแหน่งจัดเก็บ (Move to Location) และการหยิบสินค้า (Picking) ทำให้ลดความผิดพลาดและทำงานได้คล่องตัว 3. ระบบฐานข้อมูลและการประมวลผลกลาง (Core System & Database) WMS (Warehouse Management System Database): ถือเป็นหัวใจหลักหรือเซิร์ฟเวอร์กลางของโปรแกรม My Inventory ทำหน้าที่เป็นฐานข้อมูลกลาง (Centralized Database) คอยรับสัญญาณ Data Packet จากอุปกรณ์ PDA และคอมพิวเตอร์ เพื่อประมวลผลและอัปเดตสถานะสินค้าคงคลังแบบเรียลไทม์ (Update Inventory) ในทุก ๆ จุดเปลี่ยนของสถานะสินค้า 4. โครงสร้างกระบวนการทางธุรกิจ (Business Process Overview)",
    "screenDescription": "หน้าจอ User อยู่ในหมวด การตั้งค่าระบบ ใช้สำหรับ กำหนดค่าระบบและควบคุมสิทธิ์ใช้งาน ผู้ใช้งานควรตรวจสอบส่วน Header, Search/Filter, Detail Grid, Action Buttons, Status และข้อความแจ้งเตือนก่อนยืนยันรายการ",
