    "sourceExcerpt": "15. Assign Menu / Transaction Log ใช้สำหรับกำหนดเมนูและสิทธิ์การเข้าถึง เข้าสู่เมนูที่เกี่ยวข้องจากโครงสร้างเมนูหลักของระบบ ตรวจสอบข้อมูลอ้างอิง เช่น รหัสเอกสาร ผู้เกี่ยวข้อง วันที่ หรือสถานะที่ปรากฏบนหน้าจอ กรอกข้อมูลในฟิลด์ที่จำเป็น หรือเลือกคำสั่งจากปุ่ม/แถบเครื่องมือให้ครบถ้วน ทบทวนรายการในตารางหรือค่าที่ผู้ใช้สแกน/ป้อนก่อนบันทึก ยืนยัน หรือพิมพ์เอกสาร ผู้ปฏิบัติงานเปิดเมนู Authentication / Assign Menu เพื่อใช้งานหน้าจอ Assign Menu / Transaction Log โดยใช้ข้อมูลจากเอกสารอ้างอิงหรือการสแกนบาร์โค้ด จากนั้นตรวจสอบผลลัพธ์ว่ารายการได้รับการบันทึกและเปลี่ยนสถานะถูกต้อง การลบหรือซ่อนเมนูอาจกระทบผู้ใช้งานหลายกลุ่ม โครงสร้างเมนูและสิทธิ์แสดงผลถูกอัปเดต หมายเหตุ: คำอธิบายหน้าจอนี้ยึดตามภาพที่มองเห็นได้และชื่อไฟล์อ้างอิงเป็นหลัก หากบางฟิลด์หรือสิทธิ์ไม่ปรากฏในระบบจริง ให้ยึดตามการตั้งค่าหน่วยงานและบทบาทผู้ใช้ ใช้สำหรับติดตามประวัติการใช้งานและการเปลี่ยนแปลงข้อมูล ผู้ปฏิบัติงานเปิดเมนู Transaction Log เพื่อใช้งานหน้าจอ Transaction Log โดยใช้ข้อมูลจากเอกสารอ้างอิงหรือการสแกนบาร์โค้ด จากนั้นตรวจสอบผลลัพธ์ว่ารายการได้รับการบันทึกและเปลี่ยนสถานะถูกต้อง ควรใช้ตรวจสอบย้อนหลังเมื่อเกิดปัญหา สามารถตรวจสอบกิจกรรมและเหตุการณ์ย้อนหลังได้",
